from  sqlalchemy import *
from sqlalchemy.orm import *

engine = create_engine("sqlite:///data.db", echo = True)
engine.connect()

class Base(DeclarativeBase): pass

class animals(Base):
    __tablename__ = "animals"
    id = Column(Integer, primary_key=True,index=True,autoincrement=True)
    scientific_name = Column(Text,nullable=False)
    movebank_name = Column(Text,nullable=False)
    status = Column(VARCHAR,nullable=False)
    iucn_url = Column(Text,nullable=False)
    wikipedia_url = Column(Text,nullable=False)
    image_url = Column(Text,nullable=False)
    description = Column(Text,nullable=False)
    group_Name = Column(Text,nullable=False)   


class points(Base):
    __tablename__ = "points"
    id = Column(Integer, primary_key=True,index=True,autoincrement=True)
    animalId = Column(Integer, ForeignKey("animals.id"), nullable=False)
    animalа_locationLong = Column(Float,nullable=False)
    animal_locationLat = Column(Float,nullable=False)
    observed_at = Column(DateTime(timezone=True), nullable=False)
    individual = Column(VARCHAR,nullable=False)
    study_id = Column(Integer,nullable=False)


Base.metadata.create_all(engine)



